head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// saveRemovedData 값을 바꿔 DataList 를 새로 만들고, removeRow 로 Row 를 제거한 뒤
//  getDeletedJSON() 이 "E" 상태 Row 를 돌려주는지 확인한다.
scwin.buildAndRemove = function (strSave) {
    var objOld = $p.getComponentById("target1");
    if (objOld) { $p.data.remove("target1"); }

    var strDl = '<w2:dataList baseNode="list" repeatNode="map" id="target1" saveRemovedData="' + strSave + '">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    strDl += '<w2:row><col1>col1_1</col1><col2>col2_1</col2></w2:row>';
    strDl += '<w2:row><col1>col1_2</col1><col2>col2_2</col2></w2:row>';
    strDl += '<w2:row><col1>col1_3</col1><col2>col2_3</col2></w2:row>';
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';

    $p.data.create(strDl);

    // 두번째 Row 를 remove 계열 메소드로 제거한다 -> "E" 상태가 된다
    $p.getComponentById("target1").removeRow(1);
};

scwin.check = function (strSave) {
    scwin.buildAndRemove(strSave);

    var arrDeleted = $p.getComponentById("target1").getDeletedJSON();
    var arrStatus = [];
    for (var i = 0; i < arrDeleted.length; i++) {
        arrStatus.push(arrDeleted[i].col1 + "(" + arrDeleted[i].rowStatus + ")");
    }

    var bHasE = false;
    for (var k = 0; k < arrDeleted.length; k++) {
        if (arrDeleted[k].rowStatus === "E") { bHasE = true; }
    }

    scwin.setReturnValue("=====saveRemovedData = " + strSave + "=====");
    scwin.setReturnValue("    removeRow(1) 로 col1_2 Row 를 제거함");
    scwin.setReturnValue("    getDeletedJSON() 반환 건수 : " + arrDeleted.length);
    scwin.setReturnValue("    반환 내용 : " + (arrStatus.length === 0 ? "없음" : arrStatus.join(", ")));
    scwin.setReturnValue("    E 상태 Row 조회됨 : " + (bHasE ? "O" : "X"));
    scwin.setReturnValue("");
};

scwin.btn_true_onclick  = function (e) { scwin.check("true"); };
scwin.btn_false_onclick = function (e) { scwin.check("false"); };

scwin.btn_both_onclick = function (e) {
    scwin.check("true");
    scwin.check("false");

    scwin.setReturnValue("----- 판정 -----");
    var strTxt = $p.getComponentById("tbx_return").getValue();
    var nPos = strTxt.lastIndexOf("E 상태 Row 조회됨 : ");
    var strLast = strTxt.substring(nPos + "E 상태 Row 조회됨 : ".length, nPos + "E 상태 Row 조회됨 : ".length + 1);
    if (strLast === "X") {
        scwin.setReturnValue("saveRemovedData=false 일때 E 상태 Row 가 조회되지 않는다");
    } else {
        scwin.setReturnValue("saveRemovedData=false 인데도 E 상태 Row 가 조회된다 (true 와 결과가 같다)");
    }
    scwin.setReturnValue("");
};
